export function useGameEntityInteraction() {
  const { gameState, uiState, uiDispatch } = useGameState();

  const handleEntityMouseMove = (e: React.MouseEvent, entity: Unit | Building | Vehicle) => {
    e.stopPropagation();
    e.preventDefault();

