      type: "setMousePosition",
      mousePosition: {
        grid: entityGridPosition,
        screen: gridToScreenSpace(entityGridPosition, gameState.mapSize),
        browser: { x: 0, y: 0 },
        isOutOfGrid: false,
      },
    });
  };

  return { handleEntityMouseMove };
}

