export function applyAction(
  state: BattleState,
  action: BattleAction,
  rng: Rng,
  movibles?: Movibles,
): void {
  if (state.finished !== null) throw new Error('la batalla ya ha terminado');
  const s = activeStack(state);
  if (s === null) throw new Error('no hay stack activo');
  if (movibles !== undefined && movibles.stack !== s.id) {
    throw new Error(`el recorrido que traes es de ${movibles.stack} y quien actÃºa es ${s.id}`);
  }

  switch (action.type) {
    case 'wait': {
      if (s.waited) throw new Error(`${s.id} ya esperÃ³ en esta ronda`);
      s.waited = true;
      state.log.push({ kind: 'wait', stack: s.id });
      state.queue.push(s.id);
      advance(state, rng);
      return;
    }

    case 'defend': {
      s.defending = true;
      state.log.push({ kind: 'defend', stack: s.id });
      endTurn(state, s, rng);
      return;
    }

    case 'move': {
      moveTo(state, s, action.to, movibles?.costs);
      endTurn(state, s, rng);
      return;
    }

    case 'attack': {
      const target = stackById(state, action.target);
      if (!isAlive(target)) throw new Error(`${target.id} ya estÃ¡ destruido`);
      if (target.side === s.side) throw new Error('no se puede atacar a un aliado');
      // Los hexes recorridos NO se guardan en el stack: viajan hasta el golpe
      // como argumento. Un campo `hexesMoved` habrÃ­a que resetearlo en
      // `beginRound` y en `endTurn`, y el dÃ­a que se olvidara uno el
      // contraatacante cargarÃ­a con los hexes de su turno anterior.
      const recorridos =
        action.from === undefined ? 0 : moveTo(state, s, action.from, movibles?.costs);
      if (!canReachMelee(s, target)) {
        throw new Error(`${s.id} no alcanza a ${target.id} cuerpo a cuerpo`);
      }
      melee(state, s, target, rng, recorridos);
      endTurn(state, s, rng);
      return;
    }

    case 'shoot': {
      const target = stackById(state, action.target);
      if (!isShooter(creature(s.creature))) throw new Error(`${s.id} no es tirador`);
      if (s.shotsLeft <= 0) throw new Error(`${s.id} se ha quedado sin municiÃ³n`);
      if (isEngaged(state, s)) throw new Error(`${s.id} tiene un enemigo encima`);
      if (!isAlive(target)) throw new Error(`${target.id} ya estÃ¡ destruido`);
      if (target.side === s.side) throw new Error('no se puede disparar a un aliado');
      shoot(state, s, target, rng);
      endTurn(state, s, rng);
      return;
    }

    case 'cast': {
      castHeroSpell(state, s.side, action.spell, action.target);
      // Lanzar un hechizo no consume el turno del stack: el hÃ©roe actÃºa aparte.
      return;
    }
  }
}

