export class DamageNumbers {
  private container: HTMLDivElement;
  private numbers: FloatingNumber[] = [];
  private camera: Camera | null = null;
  private tempVec = new Vector3();

  constructor() {
    this.container = document.createElement("div");
    this.container.className = "fixed inset-0 pointer-events-none z-[12] overflow-hidden";
    document.body.appendChild(this.container);
  }

  setCamera(camera: Camera): void {
    this.camera = camera;
  }

  spawn(x: number, y: number, z: number, damage: number, color = "#fff"): void {
    const el = document.createElement("div");
    el.textContent = `-${Math.round(damage)}`;
    el.className = "absolute text-sm font-bold font-game whitespace-nowrap will-change-[transform,opacity]";
    el.style.color = color;
    el.style.textShadow = "0 1px 3px rgba(0,0,0,0.8)";
    el.style.transform = "translate(-50%, -50%)";
    this.container.appendChild(el);

    this.numbers.push({ el, x, y: y + 0.5, z, age: 0, lifespan: LIFESPAN });
  }

  update(delta: number): void {
    if (!this.camera) return;

    const w = window.innerWidth;
    const h = window.innerHeight;

    for (let i = this.numbers.length - 1; i >= 0; i--) {
      const num = this.numbers[i];
      num.age += delta;

      if (num.age >= num.lifespan) {
        num.el.remove();
        this.numbers[i] = this.numbers[this.numbers.length - 1];
        this.numbers.pop();
        continue;
      }

      const t = num.age / num.lifespan;

      // Float upward in world space
      num.y += delta * 1.5;

      // Project to screen
      this.tempVec.set(num.x, num.y, num.z).project(this.camera);
      const screenX = (this.tempVec.x * 0.5 + 0.5) * w;
      const screenY = (-this.tempVec.y * 0.5 + 0.5) * h;

      // Behind camera check
      if (this.tempVec.z > 1) {
        num.el.style.display = "none";
        continue;
      }
      num.el.style.display = "";

      const scale = 1 + t * 0.3;
      num.el.style.transform = `translate(-50%, -50%) translate(${screenX}px, ${screenY}px) scale(${scale})`;
      num.el.style.opacity = String(1 - t);
    }
  }

  dispose(): void {
    for (const num of this.numbers) {
      num.el.remove();
    }
    this.numbers = [];
    this.container.remove();
  }
}

export class WaveManager {
  private waves: WaveConfig[];
  private enemyManager: EnemyManager;
  private eventBus: EventBus;

  private currentWave = 0;
  private entryIndex = 0;
  private spawnedInEntry = 0;
  private spawnTimer = 0;
  private state: WaveState = "idle";

  constructor(
    waves: WaveConfig[],
    enemyManager: EnemyManager,
    eventBus: EventBus,
  ) {
    this.waves = waves;
    this.enemyManager = enemyManager;
    this.eventBus = eventBus;
  }

  get waveNumber(): number {
    return this.currentWave + 1;
  }

  get totalWaves(): number {
    return this.waves.length;
  }

  get isIdle(): boolean {
    return this.state === "idle";
  }

  get isDone(): boolean {
    return this.state === "done";
  }

  startWave(): boolean {
    if (this.state !== "idle") return false;
    if (this.currentWave >= this.waves.length) return false;

    this.entryIndex = 0;
    this.spawnedInEntry = 0;
    this.spawnTimer = 0;
    this.state = "spawning";
    this.eventBus.emit("wave-start", { wave: this.currentWave + 1 });
    return true;
  }

  update(delta: number): void {
    if (this.state === "spawning") {
      this.updateSpawning(delta);
    } else if (this.state === "active") {
      // Wait for all enemies to be killed or reach goal
      if (this.enemyManager.getEnemies().length === 0) {
        this.eventBus.emit("wave-complete", { wave: this.currentWave + 1 });
        this.currentWave++;
        if (this.currentWave >= this.waves.length) {
          this.state = "done";
        } else {
          this.state = "idle";
        }
      }
    }
  }

  private updateSpawning(delta: number): void {
    const wave = this.waves[this.currentWave];
    const entry = wave.entries[this.entryIndex];

    this.spawnTimer -= delta;
    if (this.spawnTimer <= 0) {
      this.enemyManager.spawn(entry.enemyConfig);
      this.spawnedInEntry++;
      this.spawnTimer = entry.spawnInterval;

      if (this.spawnedInEntry >= entry.count) {
        this.entryIndex++;
        this.spawnedInEntry = 0;

        if (this.entryIndex >= wave.entries.length) {
          this.state = "active";
        }
      }
    }
  }

  /** Add a wave dynamically (for endless mode). */
  addWave(wave: WaveConfig): void {
    this.waves.push(wave);
  }

  dispose(): void {
    // No own resources
  }
}

export class GameStateManager {
  private state: GameState;
  private eventBus: EventBus;
  private handleEnemyKilled: (data: { reward: number }) => void;
  private handleEnemyReachedGoal: (data: { damage: number }) => void;
  private handleWaveComplete: (data: { wave: number }) => void;

  constructor(eventBus: EventBus, totalWaves: number, options: GameStateOptions = {}) {
    this.eventBus = eventBus;
    this.state = {
      gold: options.startingGold ?? STARTING_GOLD,
      lives: options.startingLives ?? STARTING_LIVES,
      wave: 0,
      totalWaves,
      level: options.level ?? 1,
      levelName: options.levelName ?? "",
      isGameOver: false,
      isWin: false,
    };

    this.handleEnemyKilled = ({ reward }) => {
      this.addGold(reward);
    };

    this.handleEnemyReachedGoal = ({ damage }) => {
      this.loseLives(damage);
    };

    this.handleWaveComplete = ({ wave }) => {
      this.state.wave = wave;
      if (wave >= totalWaves) {
        this.state.isWin = true;
        this.state.isGameOver = true;
        this.eventBus.emit("game-over", { win: true });
      }
    };

    this.eventBus.on("enemy-killed", this.handleEnemyKilled);
    this.eventBus.on("enemy-reached-goal", this.handleEnemyReachedGoal);
    this.eventBus.on("wave-complete", this.handleWaveComplete);
  }

  getState(): Readonly<GameState> {
    return this.state;
  }

  get gold(): number {
    return this.state.gold;
  }

  get lives(): number {
    return this.state.lives;
  }

  canAfford(cost: number): boolean {
    return this.state.gold >= cost;
  }

  spendGold(amount: number): boolean {
    if (!this.canAfford(amount)) return false;
    this.state.gold -= amount;
    this.eventBus.emit("gold-changed", { gold: this.state.gold });
    return true;
  }

  addGold(amount: number): void {
    this.state.gold += amount;
    this.eventBus.emit("gold-changed", { gold: this.state.gold });
  }

  private loseLives(amount: number): void {
    if (this.state.isGameOver) return;
    this.state.lives -= amount;
    this.eventBus.emit("lives-changed", { lives: this.state.lives });

    if (this.state.lives <= 0) {
      this.state.lives = 0;
      this.state.isGameOver = true;
      this.state.isWin = false;
      this.eventBus.emit("game-over", { win: false });
    }
  }

  dispose(): void {
    this.eventBus.off("enemy-killed", this.handleEnemyKilled);
    this.eventBus.off("enemy-reached-goal", this.handleEnemyReachedGoal);
    this.eventBus.off("wave-complete", this.handleWaveComplete);
  }
}

export class InfluenceMap {
  readonly rows: number;
  readonly cols: number;
  private danger: number[][];
  private cellSize: number;
  private offsetX: number;
  private offsetZ: number;

  constructor(config: MapConfig) {
    this.rows = config.rows;
    this.cols = config.cols;
    this.cellSize = config.cellSize;
    // Map centering offsets (same as GameMap/gridToWorld)
    this.offsetX = ((config.cols - 1) * config.cellSize) / 2;
    this.offsetZ = ((config.rows - 1) * config.cellSize) / 2;
    this.danger = [];
    this.clear();
  }

  /** Reset all danger values to 0. */
  clear(): void {
    this.danger = [];
    for (let r = 0; r < this.rows; r++) {
      this.danger[r] = new Array<number>(this.cols).fill(0);
    }
  }

  /**
   * Rebuild the danger map from current tower positions.
   * Each tower emits influence: danger = max(0, range - distance).
   * Overlapping tower ranges stack additively.
   */
  rebuild(towers: readonly Tower[]): void {
    this.clear();

    for (const tower of towers) {
      const towerPos = tower.getObject3D().position;
      const range = tower.config.range;
      const damage = tower.config.damage;

      // Convert world position to grid position
      const gridCol = Math.round((towerPos.x + this.offsetX) / this.cellSize);
      const gridRow = Math.round((towerPos.z + this.offsetZ) / this.cellSize);

      // Cells within range
      const cellRange = Math.ceil(range / this.cellSize);

      for (let dr = -cellRange; dr <= cellRange; dr++) {
        for (let dc = -cellRange; dc <= cellRange; dc++) {
          const r = gridRow + dr;
          const c = gridCol + dc;
          if (r < 0 || r >= this.rows || c < 0 || c >= this.cols) continue;

          // World-space distance from tower center to cell center
          const cellWorldX = c * this.cellSize - this.offsetX;
          const cellWorldZ = r * this.cellSize - this.offsetZ;
          const dx = cellWorldX - towerPos.x;
          const dz = cellWorldZ - towerPos.z;
          const dist = Math.sqrt(dx * dx + dz * dz);

          if (dist <= range) {
            // Danger falls off linearly with distance, weighted by tower damage
            const influence = (1 - dist / range) * damage;
            this.danger[r][c] += influence;
          }
        }
      }
    }
  }

  /** Get the danger value at a grid position. */
  getDanger(row: number, col: number): number {
    if (row < 0 || row >= this.rows || col < 0 || col >= this.cols) return 0;
    return this.danger[row][col];
  }

  /** Get the danger value at a world position. */
  getDangerAtWorld(worldX: number, worldZ: number): number {
    const col = Math.round((worldX + this.offsetX) / this.cellSize);
    const row = Math.round((worldZ + this.offsetZ) / this.cellSize);
    return this.getDanger(row, col);
  }

  /** Get the raw danger grid (for debugging/visualization). */
  getDangerGrid(): readonly number[][] {
    return this.danger;
  }
}

