export default class BulletTower extends BaseTower {
  constructor(opt: any) {
    super(opt);

    this.type = 'BULLET';
    this.hue = 200;
    this.cost = towerData[this.type].cost;
    this.range = 3 * gridWidth;

    this.direction = opt.direction || 0; // ç”¨åº¦æ•°è¡¨ç¤ºçš„toweræŒ‡å‘
  }

  draw() {
    const ctx = this.ctx;

    // å°†æ–¹å‘å‘é‡å½’ä¸€åŒ–
    this.directionVec = vec2.fromValues(
      Math.cos(toRadians(this.direction)),
      Math.sin(toRadians(this.direction))
    );
    vec2.normalize(this.directionVec, this.directionVec);

    // bullet å‡ºå°„ä½ç½®
    vec2.scale(this.bulletStartPosVec, this.directionVec, 30);

    ctx.save();
    if (config.renderShadow) {
      ctx.shadowBlur = this.radius;
      ctx.shadowColor = 'hsl(' + this.hue + ',100%,60%)';
    }

    // åœ¨é€‰ä¸­çš„æƒ…å†µä¸‹ï¼Œç”»å‡ºå…¶å°„ç¨‹èŒƒå›´
    if (this.selected) {
      ctx.beginPath();
      ctx.fillStyle = 'rgba(200, 200, 200, 0.3)';
      ctx.arc(this.x, this.y, this.range, 0, 2 * Math.PI);
      ctx.fill();
    }

    ctx.strokeStyle = 'hsl(' + this.hue + ',100%,80%';
    ctx.fillStyle = 'hsl(' + this.hue + ',100%,80%';
    ctx.lineWidth = Math.max(3, this.radius / 8);

    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, 2 * Math.PI);
    ctx.closePath();
    ctx.stroke();
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(this.x, this.y);
    ctx.lineTo(
      this.x + this.bulletStartPosVec[0],
      this.y + this.bulletStartPosVec[1]
    );
    ctx.stroke();
    ctx.closePath();

    if (
      this.targetIndex !== -1 &&
      new Date().getTime() - this.lastShootTime.getTime() >= 500
    ) {
      this.shoot();
      this.lastShootTime = new Date();
    }

    ctx.restore();
  }

  // å‘å°„å­å¼¹
  shoot() {
    this.bullets.push(
      new CircleBullet({
        id: globalId.genId(),
        target: this.target,
        ctx: this.ctx,
        x: this.x + this.bulletStartPosVec[0],
        y: this.y + this.bulletStartPosVec[1],
        range: this.range,
        damage: this.damage,
        parent: this,
      })
    );
  }

  findTarget(enemies: EntityCollection<Enemy>) {
    return super.findTarget(enemies);
  }
}

function resolveNormalBattle(
  attackerStr: number,
  effectiveDefender: number,
  rawDefenderStr: number,
  rng: () => number
): CombatResult {
  const total = attackerStr + effectiveDefender;
  const attackerChance = attackerStr / total;
  const roll = rng();

  const winner: 'attacker' | 'defender' = roll < attackerChance ? 'attacker' : 'defender';

  // Casualties: loser takes heavier losses
  const loserCasualtyRate = 0.3 + rng() * 0.2; // 30-50%
  const winnerCasualtyRate = 0.1 + rng() * 0.1; // 10-20%

  let attackerCasualties: number;
  let defenderCasualties: number;

  if (winner === 'attacker') {
    attackerCasualties = Math.round(attackerStr * winnerCasualtyRate);
    defenderCasualties = Math.round(rawDefenderStr * loserCasualtyRate);
  } else {
    attackerCasualties = Math.round(attackerStr * loserCasualtyRate);
    defenderCasualties = Math.round(rawDefenderStr * winnerCasualtyRate);
  }

  return { winner, attackerCasualties, defenderCasualties, rounds: 1 };
}

